<script setup lang="ts">
import { computed,ref } from 'vue'
import {bytes,type Status} from '../api'
const props=defineProps<{status:Status}>();const version=ref('')
const resources=computed(()=>props.status.resources.filter(item=>!version.value||item.Resource.Labels.version===version.value))
</script>
<template><section><h2>Versions and resources</h2><label class="inline-label">Version <select v-model="version"><option value="">All versions</option><option v-for="(_,name) in status.versions" :key="name" :value="name">{{name}}</option></select></label><div class="version-list"><article v-for="(firstSeen,name) in status.versions" :key="name"><button class="secondary" @click="version=name">{{name}}</button><span class="muted">First seen {{firstSeen}} · {{status.counters['version:'+name+':requests']||0}} artifact requests</span></article><p v-if="!Object.keys(status.versions).length" class="empty">No versions discovered yet. Downloads are fetched on demand.</p></div><p class="muted">Average effective speed includes retries and excludes verification; recent speed is a five-second snapshot.</p><div class="table-wrap" v-if="resources.length"><table><thead><tr><th>Version / file</th><th>Generation / state</th><th>On disk / readers</th><th>Average / recent</th><th>Resumes / verification</th><th>Started / finished / last error</th></tr></thead><tbody><tr v-for="item in resources" :key="item.ID"><td>{{item.Resource.Labels.version}} / {{item.Resource.Labels.name}}</td><td><code>{{item.ID.slice(0,8)}}</code><br>{{item.State}}<span v-if="item.Retired"> · Pending deletion</span></td><td>{{bytes(item.Bytes)}} / {{item.Readers}}</td><td>{{bytes(item.AverageBPS)}}/s<br>{{bytes(item.RecentBPS)}}/s</td><td>{{item.Resumes}} / {{(item.VerificationNS/1e6).toFixed(1)}} ms</td><td>{{item.Started}}<br>{{item.Finished}}<br>{{item.Error||'No error'}}</td></tr></tbody></table></div><p v-else class="empty">No cached resources for this selection.</p></section></template>
